&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;No weekend or minimum requirements&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 12pt; color: rgb(204, 9, 47);&quot;&gt;&lt;strong&gt;Qualifications for Nurses:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
